// Lint a GitHub Actions workflow that runs Claude Code, against what the Claude Code GitHub Actions documentation recommends.
//
// The checks are the ones the documentation states (read on 2026-10-03): keep keys in GitHub Secrets, grant only the permissions
// the job needs, use the v1 action, cap the work of each run with --max-turns, a timeout and concurrency control, start runners only on
// comments that mention @claude, and check the repository out before a skill from it can run. Reading the workflow is plain data work:
// nothing here needs a runner, a key or a network.
import { parseYaml } from "./miniyaml.ts";
import { logger } from "./logger.ts";
const log = logger("workflow_lint");

const CLAUDE_ACTION = "anthropics/claude-code-action";
type Finding = [string, string, string];

const claudeSteps = (job: any): any[] => (job.steps ?? []).filter((s: any) => String(s.uses ?? "").startsWith(CLAUDE_ACTION));

/** Findings as [job or '-', rule id, message]. */
export function lint(text: string): Finding[] {
  const wf = parseYaml(text) as any;
  const findings: Finding[] = [];
  if (/sk-ant-[A-Za-z0-9_-]{8,}/.test(text)) findings.push(["-", "literal-key", "an API key is written into the file: use ${{ secrets.NAME }}"]);
  if (!("concurrency" in wf)) findings.push(["-", "no-concurrency", "no concurrency group: parallel runs are not limited"]);
  const triggers = wf.on;
  const names: any[] = Array.isArray(triggers) ? triggers : triggers && typeof triggers === "object" ? Object.keys(triggers) : [triggers];
  for (const [name, job] of Object.entries<any>(wf.jobs ?? {})) {
    const steps = claudeSteps(job);
    if (!steps.length) continue;
    for (const step of steps) {
      if (!String(step.uses).endsWith("@v1")) findings.push([name, "action-version", `${step.uses} is not the v1 action: move @beta workflows to @v1`]);
      const w = step.with ?? {};
      for (const field of ["anthropic_api_key", "claude_code_oauth_token"]) {
        if (field in w && !String(w[field]).startsWith("${{ secrets.")) findings.push([name, "literal-key", `${field} is not read from the secrets context`]);
      }
      if (!String(w.claude_args ?? "").includes("--max-turns")) findings.push([name, "no-max-turns", "claude_args has no --max-turns: a run has no turn limit"]);
      if (String(w.prompt ?? "").startsWith("/")) {
        const before = job.steps.slice(0, job.steps.indexOf(step));
        if (!before.some((s: any) => String(s.uses ?? "").startsWith("actions/checkout"))) findings.push([name, "no-checkout", "a skill from the repository needs actions/checkout before the Claude step"]);
      }
    }
    const perms = job.permissions;
    if (perms == null) findings.push([name, "no-permissions", "no permissions block: grant only what the job needs"]);
    else if (name.toLowerCase().includes("review") && perms.contents === "write") findings.push([name, "review-writes", "a review job has contents: write; reading is enough to review"]);
    if (!("timeout-minutes" in job)) findings.push([name, "no-timeout", "no timeout-minutes: a stuck run keeps the runner"]);
    if (names.includes("issue_comment") && !String(job.if ?? "").includes("@claude")) findings.push([name, "unguarded-trigger", "the job has no if: contains(..., '@claude'): a runner starts on every comment"]);
  }
  return findings;
}

export const BAD = `name: Claude
on:
  issue_comment:
    types: [created]
jobs:
  review:
    runs-on: ubuntu-latest
    permissions:
      contents: write
    steps:
      - uses: anthropics/claude-code-action@beta
        with:
          anthropic_api_key: sk-ant-api03-EXAMPLEEXAMPLE
          prompt: "/code-review"
`;

export const GOOD = `name: Claude review
on:
  pull_request:
    types: [opened, synchronize]
concurrency:
  group: claude-\${{ github.event.pull_request.number }}
  cancel-in-progress: true
jobs:
  review:
    runs-on: ubuntu-latest
    timeout-minutes: 15
    permissions:
      contents: read
      pull-requests: write
      id-token: write
    steps:
      - uses: actions/checkout@v6
        with:
          fetch-depth: 1
      - uses: anthropics/claude-code-action@v1
        with:
          anthropic_api_key: \${{ secrets.ANTHROPIC_API_KEY }}
          prompt: "/code-review"
          claude_args: --max-turns 8
`;

function main() {
  for (const [label, text] of [["bad workflow", BAD], ["good workflow", GOOD]]) {
    const found = lint(text);
    console.log(`${label}: ${found.length} finding(s)`);
    for (const [job, rule, message] of found) console.log(`  [${rule}] ${job}: ${message}`);
  }
}

if (import.meta.main) main();

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * Lint a GitHub Actions workflow that runs Claude Code, against what the Claude Code GitHub Actions documentation recommends.
 *
 * <p>The checks are the ones the documentation states (read on 2026-10-03): keep keys in GitHub Secrets, grant only the permissions
 * the job needs, use the v1 action, cap the work of each run with --max-turns, a timeout and concurrency control, start runners only on
 * comments that mention @claude, and check the repository out before a skill from it can run. Reading the workflow is plain data work:
 * nothing here needs a runner, a key or a network. The workflow is YAML, read with Jackson.
 */
public final class WorkflowLint {
    private static final System.Logger LOG = System.getLogger(WorkflowLint.class.getName());
    static final String CLAUDE_ACTION = "anthropics/claude-code-action";

    /** A finding: the job (or "-"), a rule id and a message. */
    record Finding(String job, String rule, String message) {}

    @SuppressWarnings("unchecked")
    static Map<String, Object> parseYaml(String text) throws IOException {
        return new ObjectMapper(new YAMLFactory()).readValue(text, LinkedHashMap.class);
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> map(Object o) {
        return o instanceof Map<?, ?> m ? (Map<String, Object>) m : Map.of();
    }

    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> steps(Map<String, Object> job) {
        return job.get("steps") instanceof List<?> l ? (List<Map<String, Object>>) l : List.of();
    }

    private static String str(Object o) {
        return o == null ? "" : String.valueOf(o);
    }

    static List<Map<String, Object>> claudeSteps(Map<String, Object> job) {
        return steps(job).stream().filter(s -> str(s.get("uses")).startsWith(CLAUDE_ACTION)).toList();
    }

    /** Findings in the order they are found. */
    static List<Finding> lint(String text) throws IOException {
        Map<String, Object> wf = parseYaml(text);
        List<Finding> findings = new ArrayList<>();
        if (Pattern.compile("sk-ant-[A-Za-z0-9_-]{8,}").matcher(text).find()) findings.add(new Finding("-", "literal-key", "an API key is written into the file: use ${{ secrets.NAME }}"));
        if (!wf.containsKey("concurrency")) findings.add(new Finding("-", "no-concurrency", "no concurrency group: parallel runs are not limited"));
        Object triggers = wf.get("on");
        List<Object> names = triggers instanceof Map<?, ?> m ? new ArrayList<>(m.keySet()) : triggers instanceof List<?> l ? new ArrayList<>(l) : java.util.Collections.singletonList(triggers);
        for (Map.Entry<String, Object> entry : map(wf.get("jobs")).entrySet()) {
            String name = entry.getKey();
            Map<String, Object> job = map(entry.getValue());
            List<Map<String, Object>> claude = claudeSteps(job);
            if (claude.isEmpty()) continue;
            for (Map<String, Object> step : claude) {
                if (!str(step.get("uses")).endsWith("@v1")) findings.add(new Finding(name, "action-version", step.get("uses") + " is not the v1 action: move @beta workflows to @v1"));
                Map<String, Object> with = map(step.get("with"));
                for (String field : List.of("anthropic_api_key", "claude_code_oauth_token")) {
                    if (with.containsKey(field) && !str(with.get(field)).startsWith("${{ secrets.")) findings.add(new Finding(name, "literal-key", field + " is not read from the secrets context"));
                }
                if (!str(with.get("claude_args")).contains("--max-turns")) findings.add(new Finding(name, "no-max-turns", "claude_args has no --max-turns: a run has no turn limit"));
                if (str(with.get("prompt")).startsWith("/")) {
                    List<Map<String, Object>> before = steps(job).subList(0, steps(job).indexOf(step));
                    if (before.stream().noneMatch(s -> str(s.get("uses")).startsWith("actions/checkout"))) {
                        findings.add(new Finding(name, "no-checkout", "a skill from the repository needs actions/checkout before the Claude step"));
                    }
                }
            }
            if (!job.containsKey("permissions") || job.get("permissions") == null) {
                findings.add(new Finding(name, "no-permissions", "no permissions block: grant only what the job needs"));
            } else if (name.toLowerCase().contains("review") && "write".equals(map(job.get("permissions")).get("contents"))) {
                findings.add(new Finding(name, "review-writes", "a review job has contents: write; reading is enough to review"));
            }
            if (!job.containsKey("timeout-minutes")) findings.add(new Finding(name, "no-timeout", "no timeout-minutes: a stuck run keeps the runner"));
            if (names.contains("issue_comment") && !str(job.get("if")).contains("@claude")) {
                findings.add(new Finding(name, "unguarded-trigger", "the job has no if: contains(..., '@claude'): a runner starts on every comment"));
            }
        }
        return findings;
    }

    static final String BAD = """
        name: Claude
        on:
          issue_comment:
            types: [created]
        jobs:
          review:
            runs-on: ubuntu-latest
            permissions:
              contents: write
            steps:
              - uses: anthropics/claude-code-action@beta
                with:
                  anthropic_api_key: sk-ant-api03-EXAMPLEEXAMPLE
                  prompt: "/code-review"
        """;

    static final String GOOD = """
        name: Claude review
        on:
          pull_request:
            types: [opened, synchronize]
        concurrency:
          group: claude-${{ github.event.pull_request.number }}
          cancel-in-progress: true
        jobs:
          review:
            runs-on: ubuntu-latest
            timeout-minutes: 15
            permissions:
              contents: read
              pull-requests: write
              id-token: write
            steps:
              - uses: actions/checkout@v6
                with:
                  fetch-depth: 1
              - uses: anthropics/claude-code-action@v1
                with:
                  anthropic_api_key: ${{ secrets.ANTHROPIC_API_KEY }}
                  prompt: "/code-review"
                  claude_args: --max-turns 8
        """;

    public static void main(String[] args) throws IOException {
        for (Map.Entry<String, String> e : List.of(Map.entry("bad workflow", BAD), Map.entry("good workflow", GOOD))) {
            List<Finding> found = lint(e.getValue());
            System.out.println(e.getKey() + ": " + found.size() + " finding(s)");
            for (Finding f : found) System.out.println("  [" + f.rule() + "] " + f.job() + ": " + f.message());
        }
    }
}

import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory

private val log = System.getLogger("workflow_lint")

/**
 * Lint a GitHub Actions workflow that runs Claude Code, against what the Claude Code GitHub Actions documentation recommends.
 *
 * The checks are the ones the documentation states (read on 2026-10-03): keep keys in GitHub Secrets, grant only the permissions
 * the job needs, use the v1 action, cap the work of each run with --max-turns, a timeout and concurrency control, start runners only on
 * comments that mention @claude, and check the repository out before a skill from it can run. Reading the workflow is plain data work:
 * nothing here needs a runner, a key or a network. The workflow is YAML, read with Jackson.
 */
const val CLAUDE_ACTION = "anthropics/claude-code-action"

/** A finding: the job (or "-"), a rule id and a message. */
data class Finding(val job: String, val rule: String, val message: String)

typealias Node = Map<String, Any?>

@Suppress("UNCHECKED_CAST")
fun parseYaml(text: String): Node = ObjectMapper(YAMLFactory()).readValue(text, LinkedHashMap::class.java) as Node

@Suppress("UNCHECKED_CAST")
private fun node(o: Any?): Node = o as? Node ?: emptyMap()

@Suppress("UNCHECKED_CAST")
private fun steps(job: Node): List<Node> = job["steps"] as? List<Node> ?: emptyList()

private fun str(o: Any?) = o?.toString() ?: ""

fun claudeSteps(job: Node): List<Node> = steps(job).filter { str(it["uses"]).startsWith(CLAUDE_ACTION) }

/** Findings in the order they are found. */
fun lint(text: String): List<Finding> {
    val wf = parseYaml(text)
    val findings = mutableListOf<Finding>()
    if (Regex("sk-ant-[A-Za-z0-9_-]{8,}").containsMatchIn(text)) findings += Finding("-", "literal-key", "an API key is written into the file: use \${{ secrets.NAME }}")
    if ("concurrency" !in wf) findings += Finding("-", "no-concurrency", "no concurrency group: parallel runs are not limited")
    val triggers = wf["on"]
    val names: List<Any?> = when (triggers) {
        is Map<*, *> -> triggers.keys.toList()
        is List<*> -> triggers
        else -> listOf(triggers)
    }
    for ((name, jobValue) in node(wf["jobs"])) {
        val job = node(jobValue)
        val claude = claudeSteps(job)
        if (claude.isEmpty()) continue
        for (step in claude) {
            if (!str(step["uses"]).endsWith("@v1")) findings += Finding(name, "action-version", "${step["uses"]} is not the v1 action: move @beta workflows to @v1")
            val with = node(step["with"])
            for (field in listOf("anthropic_api_key", "claude_code_oauth_token")) {
                if (field in with && !str(with[field]).startsWith("\${{ secrets.")) findings += Finding(name, "literal-key", "$field is not read from the secrets context")
            }
            if ("--max-turns" !in str(with["claude_args"])) findings += Finding(name, "no-max-turns", "claude_args has no --max-turns: a run has no turn limit")
            if (str(with["prompt"]).startsWith("/")) {
                val before = steps(job).take(steps(job).indexOf(step))
                if (before.none { str(it["uses"]).startsWith("actions/checkout") }) {
                    findings += Finding(name, "no-checkout", "a skill from the repository needs actions/checkout before the Claude step")
                }
            }
        }
        val perms = job["permissions"]
        if (perms == null) {
            findings += Finding(name, "no-permissions", "no permissions block: grant only what the job needs")
        } else if ("review" in name.lowercase() && node(perms)["contents"] == "write") {
            findings += Finding(name, "review-writes", "a review job has contents: write; reading is enough to review")
        }
        if ("timeout-minutes" !in job) findings += Finding(name, "no-timeout", "no timeout-minutes: a stuck run keeps the runner")
        if ("issue_comment" in names && "@claude" !in str(job["if"])) {
            findings += Finding(name, "unguarded-trigger", "the job has no if: contains(..., '@claude'): a runner starts on every comment")
        }
    }
    return findings
}

val BAD = """name: Claude
on:
  issue_comment:
    types: [created]
jobs:
  review:
    runs-on: ubuntu-latest
    permissions:
      contents: write
    steps:
      - uses: anthropics/claude-code-action@beta
        with:
          anthropic_api_key: sk-ant-api03-EXAMPLEEXAMPLE
          prompt: "/code-review"
"""

val GOOD = """name: Claude review
on:
  pull_request:
    types: [opened, synchronize]
concurrency:
  group: claude-${"$"}{{ github.event.pull_request.number }}
  cancel-in-progress: true
jobs:
  review:
    runs-on: ubuntu-latest
    timeout-minutes: 15
    permissions:
      contents: read
      pull-requests: write
      id-token: write
    steps:
      - uses: actions/checkout@v6
        with:
          fetch-depth: 1
      - uses: anthropics/claude-code-action@v1
        with:
          anthropic_api_key: ${"$"}{{ secrets.ANTHROPIC_API_KEY }}
          prompt: "/code-review"
          claude_args: --max-turns 8
