fun main() {
    for ((label, text) in listOf("bad workflow" to BAD, "good workflow" to GOOD)) {
        val found = lint(text)
        println("$label: ${found.size} finding(s)")
        for (f in found) println("  [${f.rule}] ${f.job}: ${f.message}")
    }
}
